/**
 * Resolves official VTU credits for a given subject code.
 * Handles exact matches, branch/semester contexts, non-credit audit courses,
 * and VTU NEP elective & pattern mappings.
 */
export function getOfficialCredit(subjectCode, scheme = '2022', branch = null, semester = null) {
    if (!subjectCode) return null;
    const cleanCode = String(subjectCode).toUpperCase().trim();
    const cleanScheme = String(scheme || '2022').trim();
    const cleanBranch = branch ? String(branch).toUpperCase().trim() : null;
    const numSem = semester ? Number(semester) : null;

    // 1. Mandatory Non-Credit Audit Courses in VTU NEP 2022/2025:
    // Physical Education (BPEK*), NSS (BNSK*), Yoga (BYOK*), Indian Knowledge System (BIKS*) in sem 6 are 0 credits towards SGPA
    if (
        cleanCode.startsWith('BPEK') ||
        cleanCode.startsWith('BNSK') ||
        cleanCode.startsWith('BYOK') ||
        cleanCode.startsWith('BIKS') ||
        cleanCode.startsWith('1BPEK') ||
        cleanCode.startsWith('1BNSK') ||
        cleanCode.startsWith('1BYOK')
    ) {
        return 0;
    }

    // 2. Foundation 1-credit mandatory courses (Kannada, English, Constitution, Health, IDT, Values)
    if (/^(BKSK|BKOK|BPWS|BENG|BICO|BSFH|BIDT|KIDT|BSCK|BUHK)/i.test(cleanCode)) {
        return 1;
    }

    // 3. Exact hierarchical lookup: scheme + branch + semester + code
    if (cleanBranch && numSem) {
        const fullKey = `${cleanScheme}_${cleanBranch}_${numSem}_${cleanCode}`;
        if (OFFICIAL_CREDITS_LOOKUP[fullKey] !== undefined) {
            return OFFICIAL_CREDITS_LOOKUP[fullKey];
        }
    }

    // 4. Exact scheme + code lookup
    const schemeKey = `${cleanScheme}_${cleanCode}`;
    if (OFFICIAL_CREDITS_LOOKUP[schemeKey] !== undefined) {
        return OFFICIAL_CREDITS_LOOKUP[schemeKey];
    }

    // 5. Exact code lookup
    if (OFFICIAL_CREDITS_LOOKUP[cleanCode] !== undefined) {
        return OFFICIAL_CREDITS_LOOKUP[cleanCode];
    }

    // 6. Common VTU NEP Pattern Fallbacks:
    // Ability Enhancement Courses (AEC: e.g. BCS358x, BCS456x, BAIL657x, BCS657x, BXX657x) -> 1 credit
    if (/^[A-Z0-9]{2,5}(358|456|657)[A-Z0-9]?$/i.test(cleanCode)) {
        return 1;
    }

    // Laboratory Courses (e.g. BCSL305, BCSL404, BCSL504, BCSL606, 1BCSL*) -> 1 credit
    if (cleanCode.includes('L') && /^[A-Z0-9]{2,5}L\d{3}[A-Z0-9]?$/i.test(cleanCode)) {
        return 1;
    }

    // Mini Project & Project Phase-I (e.g. BCS586, BCS685, 1BCS685) -> 2 credits
    if (/^[A-Z0-9]{2,5}(586|685)$/i.test(cleanCode)) {
        return 2;
    }

    // Major Project Phase-II (e.g. BCS786) -> 6 credits
    if (/^[A-Z0-9]{2,5}786$/i.test(cleanCode)) {
        return 6;
    }

    // Internship (e.g. BCS803, 1BXX803X) -> 10 credits (or 9 in 2025)
    if (/^[A-Z0-9]{2,5}803[A-Z0-9]?$/i.test(cleanCode)) {
        return cleanScheme === '2025' ? 9 : 10;
    }

    // Biology for Engineers (e.g. BBOC407, BBOK407) -> 2 credits
    if (/^BB[A-Z0-9]{2}407$/i.test(cleanCode)) {
        return 2;
    }

    // Environmental Studies & E-waste (e.g. BCS508) -> 2 credits
    if (/^[A-Z0-9]{2,5}508$/i.test(cleanCode)) {
        return 2;
    }

    // Research Methodology & IPR (e.g. BRMK557) -> 3 credits
    if (/^BRM[A-Z0-9]{1,3}557$/i.test(cleanCode)) {
        return 3;
    }

    // Professional Electives & Open Electives (PEC / OEC -> 3 credits)
    // Sem 3 ESC/ETC (BCS306x), Sem 4 ESC/ETC (BCS405x), Sem 5 PEC (BCS515x), Sem 6 PEC (BCS613x), Sem 6 OEC (BEE654x, BTEC654x), Sem 7 PEC/OEC (714, 755), Sem 8 (801, 802)
    if (/^[A-Z0-9]{2,5}(306|405|515|613|654|714|755|801|802)[A-Z0-9]?$/i.test(cleanCode)) {
        return 3;
    }

    // 4-credit Core / Heavy Theory courses:
    // Maths, Physics, Chemistry, Digital Design, OS, Microcontrollers, DBMS, TOC, Networks, Cloud, ML, IoT, Cryptography
    if (/^[A-Z0-9]{2,5}(101|102|201|202|301|302|303|402|403|502|503|601|602|701|702|703)$/i.test(cleanCode)) {
        return 4;
    }

    // 3-credit Standard Theory courses:
    if (/^[A-Z0-9]{2,5}(103|104|105|203|204|205|304|401|501)[A-Z0-9]?$/i.test(cleanCode)) {
        return 3;
    }

    return null;
}
